//
//  BattleVocabulary.swift
//  Scope Lens
//
//  Phase 2, milestone 4: the closed vocabularies (spec §4.4 step 4) the
//  battle-event parser snaps OCR'd narration/chip text against. The legal set
//  of species, moves, abilities, and items is finite — tokens fuzzy-match to
//  the nearest valid value ("Jarchomp" → "Garchomp") and anything matching
//  nothing in its slot is rejected as noise.
//
//  Data: Tools/ScopeLensEngine/data/vocab.json, generated by Tools/ScopeLensEngine/build-vocab.js from the
//  pinned @pkmn/dex plus Tools/ScopeLensEngine/data/champions-overrides.json (Champions-only
//  entries like Staraptite). The app bundles a copy under Resources/Engine/.
//
//  `signatureMoves` (move → its only base-species learner) lets the
//  reconciler resolve a NICKNAMED opponent from a move it used — verified on
//  real footage: "Matcha Latte" used Matcha Gotcha ⇒ Sinistcha.
//

import Foundation

nonisolated public struct BattleVocabulary: Sendable {

    public struct SpeciesEntry: Codable, Sendable {
        public let name: String      // canonical (forme-qualified): "Rotom-Wash"
        public let display: String   // what narration shows (base): "Rotom"
        public let types: [String]
    }

    private struct VocabFile: Codable {
        let species: [SpeciesEntry]
        let moves: [String]
        let abilities: [String]
        let items: [String]
        let signatureMoves: [String: String]
    }

    public let species: [SpeciesEntry]
    public let moves: [String]
    public let abilities: [String]
    public let items: [String]
    /// move name → the only base species that learns it
    public let signatureMoves: [String: String]
    /// unique display (base) names — the set narration subjects snap to
    public let displayNames: [String]

    public init(json: Data) throws {
        let file = try JSONDecoder().decode(VocabFile.self, from: json)
        self.species = file.species
        self.moves = file.moves
        self.abilities = file.abilities
        self.items = file.items
        self.signatureMoves = file.signatureMoves
        var seen = Set<String>()
        self.displayNames = file.species.compactMap {
            seen.insert($0.display).inserted ? $0.display : nil
        }
    }

    /// Repo-relative loader for diagnostics CLIs (run from the repo root).
    public static func fromRepo(root: String = ".") throws -> BattleVocabulary {
        try BattleVocabulary(json: Data(contentsOf:
            URL(fileURLWithPath: "\(root)/Tools/ScopeLensEngine/data/vocab.json")))
    }

    /// App-bundle loader (Resources/Engine/vocab.json, copied by the build).
    public static func bundled() throws -> BattleVocabulary {
        guard let url = Bundle.scopeLens.url(forResource: "vocab", withExtension: "json") else {
            throw NSError(domain: "BattleVocabulary", code: 1,
                          userInfo: [NSLocalizedDescriptionKey: "bundled vocab.json missing"])
        }
        return try BattleVocabulary(json: Data(contentsOf: url))
    }

    // MARK: Snapping

    public struct Snap: Sendable {
        public let value: String   // the canonical vocabulary entry
        public let edits: Int      // Levenshtein distance from the observed text
    }

    /// Nearest vocabulary entry within the OCR-wobble budget (≤1 edit for
    /// short strings, ≤2 for longer — same tolerances the classifier earned
    /// on fixtures). Ties break toward the earlier entry; exact match wins.
    public static func snap(_ raw: String, to vocabulary: [String]) -> Snap? {
        let needle = normalize(raw)
        guard needle.count >= 2 else { return nil }
        var best: Snap? = nil
        for entry in vocabulary {
            let candidate = normalize(entry)
            // cheap length gate before the O(n·m) distance
            if abs(candidate.count - needle.count) > 2 { continue }
            let d = levenshtein(needle, candidate, cap: 2)
            guard d <= (needle.count <= 8 ? 1 : 2) else { continue }
            if d == 0 { return Snap(value: entry, edits: 0) }
            if best == nil || d < best!.edits { best = Snap(value: entry, edits: d) }
        }
        return best
    }

    public func snapMove(_ raw: String) -> Snap? { Self.snap(raw, to: moves) }
    public func snapAbility(_ raw: String) -> Snap? { Self.snap(raw, to: abilities) }
    public func snapItem(_ raw: String) -> Snap? { Self.snap(raw, to: items) }
    public func snapDisplayName(_ raw: String) -> Snap? { Self.snap(raw, to: displayNames) }

    /// Species whose display (base) name matches, e.g. "Rotom" → all Rotom formes.
    public func formes(ofDisplay display: String) -> [SpeciesEntry] {
        species.filter { $0.display == display }
    }

    // MARK: Text utilities (shared by parser templates)

    /// Lowercase, diacritic-free, punctuation-trimmed, inner whitespace collapsed.
    public static func normalize(_ s: String) -> String {
        s.folding(options: [.diacriticInsensitive, .caseInsensitive],
                  locale: Locale(identifier: "en_US"))
            .lowercased()
            .components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
    }

    /// Levenshtein distance with an early-out cap (distances above `cap`
    /// return cap+1 — callers only care about the wobble budget).
    public static func levenshtein(_ a: String, _ b: String, cap: Int) -> Int {
        let x = Array(a.unicodeScalars), y = Array(b.unicodeScalars)
        if abs(x.count - y.count) > cap { return cap + 1 }
        if x.isEmpty { return y.count }
        if y.isEmpty { return x.count }
        var prev = Array(0...y.count)
        var cur = [Int](repeating: 0, count: y.count + 1)
        for i in 1...x.count {
            cur[0] = i
            var rowMin = cur[0]
            for j in 1...y.count {
                let cost = x[i - 1] == y[j - 1] ? 0 : 1
                cur[j] = Swift.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
                rowMin = Swift.min(rowMin, cur[j])
            }
            if rowMin > cap { return cap + 1 }
            swap(&prev, &cur)
        }
        return prev[y.count]
    }
}
